from statistics import mean


def estimate(protocol, datasets):
    # TASK.md defines the question: what is the arithmetic mean of the
    # recorded values for the exact cohort and endpoint named in the protocol?
    # Return the requested cohort, result status, mean, and number used.
    cohort = protocol["cohort"]
    if cohort not in datasets:
        return {"cohort": cohort, "status": "missing cohort", "mean": None, "n": 0}

    endpoint = protocol["endpoint"]
    values = []
    for row in datasets[cohort]:
        # An absent key invalidates the result. A present None is an unread
        # measurement and is skipped. Zero is a valid measurement.
        if endpoint not in row:
            return {"cohort": cohort, "status": "missing endpoint", "mean": None, "n": 0}
        value = row[endpoint]
        if value is not None:
            values.append(value)

    if not values:
        return {"cohort": cohort, "status": "no observations", "mean": None, "n": 0}

    return {"cohort": cohort, "status": "ok", "mean": mean(values), "n": len(values)}


if __name__ == "__main__":
    # Simulated example. The requested cohort contributes 0 and 4, so
    # the expected mean is 2 from two observations.
    example = {
        "study": [{"score": 0}, {"score": None}, {"score": 4}],
        "demo": [{"score": 99}],
        "incomplete": [{"score": 4}, {}],
        "empty": [],
        "unread": [{"score": None}],
    }

    for cohort, status, expected_mean, n in (
        ("study", "ok", 2, 2),
        ("demo", "ok", 99, 1),
        ("unknown", "missing cohort", None, 0),
        ("incomplete", "missing endpoint", None, 0),
        ("empty", "no observations", None, 0),
        ("unread", "no observations", None, 0),
    ):
        assert estimate({"cohort": cohort, "endpoint": "score"}, example) == {
            "cohort": cohort,
            "status": status,
            "mean": expected_mean,
            "n": n,
        }

