    values = []
    for row in datasets[cohort]:
        # A missing key invalidates the result, even if earlier rows had readings.
        if endpoint not in row:
            result["status"] = "missing endpoint"
            return result
        value = row[endpoint]
        if value is not None:
            values.append(value)

    if not values:
        result["status"] = "no observations"
