import math


def estimate(protocol, datasets):
    """Mean of the requested endpoint for the exactly requested cohort.

    Repairs to the original:
    - No silent fallback to the "demo" cohort. Demo data are used only if the
      protocol explicitly requests cohort == "demo" (which is then just an
      ordinary exact lookup).
    - `if value` dropped legitimate zeros; only None is ignored now.
    - An endpoint absent from ANY record means the data do not support the
      result -> "missing endpoint" (checked before the None filtering).
    - Empty cohort / all-None readings -> "no observations" instead of a
      ZeroDivisionError.
    - Missing cohort -> "missing cohort".
    """
    cohort = protocol["cohort"]
    endpoint = protocol["endpoint"]

    def result(status, mean=None, n=0):
        return {"cohort": cohort, "status": status, "mean": mean, "n": n}

    if cohort not in datasets:
        return result("missing cohort")

    rows = datasets[cohort]
    if not rows:
        return result("no observations")

    # Absent key (not merely None) in any record -> unsupported.
    if any(endpoint not in row for row in rows):
        return result("missing endpoint")

    values = [row[endpoint] for row in rows if row[endpoint] is not None]
    if not values:
        return result("no observations")

    return result("ok", math.fsum(values) / len(values), len(values))


if __name__ == "__main__":
    # Small check.
    data = {
        "A": [{"x": 0}, {"x": 4}, {"x": None}],
        "B": [{"x": 1}, {"y": 2}],
        "C": [],
        "D": [{"x": None}],
        "demo": [{"x": 100}],
    }
    assert estimate({"cohort": "A", "endpoint": "x"}, data) == {
        "cohort": "A", "status": "ok", "mean": 2.0, "n": 2}  # zero kept, None dropped
    assert estimate({"cohort": "B", "endpoint": "x"}, data)["status"] == "missing endpoint"
    assert estimate({"cohort": "C", "endpoint": "x"}, data)["status"] == "no observations"
    assert estimate({"cohort": "D", "endpoint": "x"}, data)["status"] == "no observations"
    r = estimate({"cohort": "Z", "endpoint": "x"}, data)  # no demo fallback
    assert r == {"cohort": "Z", "status": "missing cohort", "mean": None, "n": 0}
    assert estimate({"cohort": "demo", "endpoint": "x"}, data)["mean"] == 100.0
    print("ok")

