def compare(schedule, log):
    """Compare skill with baseline over the fixed schedule, with higher scores better."""
    pairs = set(schedule)
    runs = {}
    for case, repetition, condition, status, score in log:
        pair = (case, repetition)
        if pair not in pairs or condition not in ("baseline", "skill"):
            raise ValueError(f"Unplanned run: {(case, repetition, condition)!r}")
        key = (case, repetition, condition)
        if key in runs:
            raise ValueError(f"Duplicate run: {key!r}")
        runs[key] = (status, score)

    baseline_scores = []
    skill_scores = []
    complete_differences = []
    for case, repetition in pairs:
        baseline_status, baseline_score = runs.get(
            (case, repetition, "baseline"), ("missing", None)
        )
        skill_status, skill_score = runs.get(
            (case, repetition, "skill"), ("missing", None)
        )

        # Score each planned run. Preserve its recorded outcome so that a
        # completed run scoring zero still qualifies for the paired analysis.
        baseline_scores.append(baseline_score if baseline_status == "ok" else 0)
        skill_scores.append(skill_score if skill_status == "ok" else 0)
        if baseline_status == skill_status == "ok":
            complete_differences.append(skill_score - baseline_score)

    return {
        "delta_all": mean(skill_scores) - mean(baseline_scores) if pairs else None,
        "delta_complete": mean(complete_differences) if complete_differences else None,
        "planned_pairs": len(pairs),
        "complete_pairs": len(complete_differences),
    }


if __name__ == "__main__":
    schedule = [("a", 1), ("a", 2), ("b", 1), ("c", 1)]
    log = [
        ("a", 2, "skill", "ok", 0.25),
        ("a", 1, "baseline", "ok", 0.0),
        ("b", 1, "skill", "crash", None),
        ("a", 1, "skill", "ok", 0.5),
        ("b", 1, "baseline", "ok", 1.0),
        ("a", 2, "baseline", "timeout", None),
    ]
    # By hand, skill totals 0.75 and baseline totals 1 across four pairs.
    # Only ("a", 1) completed on both sides, for a difference of 0.5.
    assert compare(schedule, log) == {
        "delta_all": -0.0625,
        "delta_complete": 0.5,
        "planned_pairs": 4,
        "complete_pairs": 1,
    }
    assert compare(schedule, []) == {
        "delta_all": 0,
        "delta_complete": None,
        "planned_pairs": 4,
        "complete_pairs": 0,
    }
    assert compare([], []) == {
        "delta_all": None,
        "delta_complete": None,
        "planned_pairs": 0,
        "complete_pairs": 0,
    }
    for invalid_entry in (log[2], ("a", 3, "skill", "ok", 1.0)):
        try:
            compare(schedule, log + [invalid_entry])
        except ValueError:
            pass
        else:
            raise AssertionError(f"Accepted invalid entry {invalid_entry!r}")

def audit_claims(draft, figures, version):
    # Repair: the original stub marked every claim "keep". Each claim is now
    # checked against the figure for its group in the *current* version.
    # Assumptions:
    #  - at most one figure matches a (group, version) pair, as the task states;
    #  - the group name is used verbatim in the revised sentence template;
    #  - percent is round(100 * positive / observed) using Python's round.

    current = {}
    for fig in figures:
        if fig.get("version") == version:
            current.setdefault(fig.get("group"), fig)

    results = []
    for claim in draft:
        fig = current.get(claim["group"])
        observed = fig.get("observed") if fig is not None else None

        # No current figure, or no respondents with an observed outcome.
        if fig is None or not observed:
            results.append({
                "id": claim["id"],
                "status": "unsupported",
                "figure": None,
                "percent": None,
                "text": "The current survey does not establish this result.",
            })
            continue

        positive = fig["positive"]
        percent = round(100 * positive / observed)

        if (claim["kind"] == "rate"
                and claim["figure"] == fig["id"]
                and claim["percent"] == percent):
            results.append({
                "id": claim["id"],
                "status": "keep",
                "figure": fig["id"],
                "percent": percent,
                "text": claim["text"],
            })
        else:
            # Wrong percentage, stale figure, or causal claim: rewrite with the
            # publication template and drop any causal interpretation.
            text = (f"{claim['group']}: {positive} of {observed} respondents "
                    f"({percent}%) reported improvement.")
            results.append({
                "id": claim["id"],
                "status": "revise",
                "figure": fig["id"],
                "percent": percent,
                "text": text,
            })

    return results

