import math


def estimate(protocol, datasets):
    """Mean of the requested endpoint for the exactly-named cohort.

    Repairs relative to the original:
    - No silent fallback to the "demo" cohort. Demo data are used only when
      the protocol explicitly asks for cohort "demo" (exact name match).
    - Missing cohort -> status "missing cohort".
    - Any record lacking the endpoint key -> "missing endpoint" (the data do
      not support the requested result). A present None is a missing reading,
      not an absent endpoint.
    - Falsy filter bug fixed: 0 is a valid value; only None is ignored.
    - Empty cohort or all None -> "no observations" (no division by zero).
    - Failure outcomes return mean None and n 0.

    Example:
      datasets = {"A": [{"x": 0}, {"x": 2}, {"x": None}], "demo": [{"x": 99}],
                  "B": [{"x": 1}, {"y": 3}], "E": []}
      estimate({"cohort": "A", "endpoint": "x"}, datasets)
        -> ok, mean 1.0, n 2   (zero kept, None ignored)
      estimate({"cohort": "C", "endpoint": "x"}, datasets)
        -> missing cohort (demo not substituted)
      estimate({"cohort": "B", "endpoint": "x"}, datasets)
        -> missing endpoint
      estimate({"cohort": "E", "endpoint": "x"}, datasets)
        -> no observations
    """
    cohort = protocol["cohort"]
    endpoint = protocol["endpoint"]

    def result(status, mean=None, n=0):
        return {"cohort": cohort, "status": status, "mean": mean, "n": n}

    if cohort not in datasets:
        return result("missing cohort")

    rows = datasets[cohort]
    if rows is None:
        rows = []

    # Any record without the endpoint key means the data don't support it.
    for row in rows:
        if endpoint not in row:
            return result("missing endpoint")

    values = [row[endpoint] for row in rows if row[endpoint] is not None]

    if not values:
        return result("no observations")

    return result("ok", math.fsum(values) / len(values), len(values))
